macro_rules! deps {
    () => {
        Parser!();
        Position!();
    };
}

macro_rules! Token {
    () => {
        deps!();
        # [doc = " A token generated by a `Parser`."] # [derive (Clone , Debug , Eq , Hash , PartialEq)] pub enum Token < 'i , R > { # [doc = " The starting `Position` of a matched `Rule`"] Start { # [doc = " matched rule"] rule : R , # [doc = " starting position"] pos : Position < 'i > , } , # [doc = " The ending `Position` of a matched `Rule`"] End { # [doc = " matched rule"] rule : R , # [doc = " ending position"] pos : Position < 'i > , } , }
    };
}

Token!();